import{_ as i,W as o,s as l,u as d,ah as r,I as t,w as s,Z as a,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"在 Linux 下如何查看一个进程的运行时间 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下如何查看一个进程的运行时间 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下如何查看一个进程的运行时间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下如何查看一个进程的运行时间 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160801 Linux how long a process has been running","title":"在 Linux 下如何查看一个进程的运行时间","tag":"201608"},"relativePath":"201608/20160801 Linux how long a process has been running.md","filePath":"[post].md"}'),h={name:"201608/20160801 Linux how long a process has been running.md"};function u(c,e,g,b,m,v){const n=o("Link");return d(),l("div",null,[e[13]||(e[13]=r(`<h1 id="在-linux-下如何查看一个进程的运行时间" tabindex="-1">在 Linux 下如何查看一个进程的运行时间 <a class="header-anchor" href="#在-linux-下如何查看一个进程的运行时间" aria-label="Permalink to 在 Linux 下如何查看一个进程的运行时间">​</a></h1><p><img src="http://s0.cyberciti.org/images/category/old/linux-logo.png" alt=""></p><blockquote><p>我是一个 Linux 系统的新手。我该如何在我的 Ubuntu 服务器上查看一个进程（或者根据进程 id 查看）已经运行了多久？</p></blockquote><p>你需要使用 ps 命令来查看关于一组正在运行的进程的信息。ps 命令提供了如下的两种格式化选项。</p><ol><li>etime 显示了自从该进程启动以来，经历过的时间，格式为 <code>[[DD-]hh:]mm:ss</code>。</li><li>etimes 显示了自该进程启动以来，经历过的时间，以秒的形式。</li></ol><h3 id="如何查看一个进程已经运行的时间" tabindex="-1">如何查看一个进程已经运行的时间？ <a class="header-anchor" href="#如何查看一个进程已经运行的时间" aria-label="Permalink to 如何查看一个进程已经运行的时间？">​</a></h3><p>你需要在 ps 命令之后添加 -o etimes 或者 -o etime 参数。它的语法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -p {PID-HERE} -o etime</span></span>
<span class="line"><span>ps -p {PID-HERE} -o etimes</span></span></code></pre></div><h4 id="第一步-找到一个进程的-pid-openvpn-为例" tabindex="-1">第一步：找到一个进程的 PID (openvpn 为例) <a class="header-anchor" href="#第一步-找到一个进程的-pid-openvpn-为例" aria-label="Permalink to 第一步：找到一个进程的 PID (openvpn 为例)">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pidof openvpn</span></span>
<span class="line"><span>6176</span></span></code></pre></div><h4 id="第二步-openvpn-进程运行了多长时间" tabindex="-1">第二步：openvpn 进程运行了多长时间？ <a class="header-anchor" href="#第二步-openvpn-进程运行了多长时间" aria-label="Permalink to 第二步：openvpn 进程运行了多长时间？">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ps -p 6176 -o etime</span></span></code></pre></div><p>或者</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ps -p 6176 -o etimes</span></span></code></pre></div><p>隐藏输出头部：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ps -p 6176 -o etime=</span></span>
<span class="line"><span>$ ps -p 6176 -o etimes=</span></span></code></pre></div><p>样例输出：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2016/08/How-to-check-how-long-a-process-has-been-running.jpg" alt=""></p><p>这个 6176 就是你想查看的进程的 PID。在这个例子中，我查看的是 openvpn 进程。你可以按照你的需求随意的更换 openvpn 进程名或者是 PID。在下面的例子中，我打印了 PID、执行命令、运行时间、用户 ID、和用户组 ID：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ps -p 6176 -o pid,cmd,etime,uid,gid</span></span></code></pre></div><p>样例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  PID CMD                             ELAPSED   UID   GID</span></span>
<span class="line"><span> 6176 /usr/sbin/openvpn --daemon        15:25 65534 65534</span></span></code></pre></div><hr>`,23)),t("p",null,[e[1]||(e[1]=s("via: ")),a(n,{href:"http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/"},{default:p(()=>e[0]||(e[0]=[s("http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/")])),_:1})]),t("p",null,[e[5]||(e[5]=s("作者：")),a(n,{href:"http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/"},{default:p(()=>e[2]||(e[2]=[s("VIVEK GITE")])),_:1}),e[6]||(e[6]=s(" 译者：")),a(n,{href:"https://github.com/MikeCoder"},{default:p(()=>e[3]||(e[3]=[s("MikeCoder")])),_:1}),e[7]||(e[7]=s(" 校对：")),a(n,{href:"https://github.com/wxy"},{default:p(()=>e[4]||(e[4]=[s("wxy")])),_:1})]),t("p",null,[e[10]||(e[10]=s("本文由 ")),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>e[8]||(e[8]=[s("LCTT")])),_:1}),e[11]||(e[11]=s(" 原创编译，")),a(n,{href:"https://linux.cn/"},{default:p(()=>e[9]||(e[9]=[s("Linux中国")])),_:1}),e[12]||(e[12]=s(" 荣誉推出"))])])}const f=i(h,[["render",u]]);export{C as __pageData,f as default};
